parts.bodyCss:
body {
                                        			height:842px;
                                        			width: 725px;
                                        			line-height: 14px;
                                              font-size:8px;
                                        			font-family: 'Source Sans Pro', sans-serif;
                                        			/* to centre page on screen*/
                                        			margin-left: auto;
                                        			margin-right: auto;
                                              
                                        		}

table {
              border-collapse: collapse;
              width: 100%;
            }

td, th {
              border: 0.5px solid black;
              padding: 3px;
            }

/* tr:nth-child(even){background-color: #f2f2f2;}

*/

            /* tr:hover {background-color: #ddd;}

*/

            th {
              padding-top: 12px;
              padding-bottom: 12px;
              text-align: left;
              background-color: #04AA6D;
              color: white;
            }

.title {
                  color:#0f1b61;
                  font-weight:bold;
                  font-size:18px;
                  }

.title-black {
                  font-size:16px;
                  }

.customtd {
                  display:inline-block;
                  border-right: 0.5px solid black;  /* Only right border */
                  padding-left:8px;
                  padding-right:8px;
                  padding-top: 8px;
                  padding-bottom: 8px;
                  height:4px;
                  width:5px;
                  font-weight:bold;
                  }

.lastcustomtd {
                  display:inline-block;
                  padding-left:8px;
                  padding-right:8px;
                  padding-top: 8px;
                  padding-bottom: 8px;
                  height:4px;
                  width:4px;
                  font-weight:bold;
                  }

.checkbox {
      position: relative;
          display: inline-block;
          width: 12px;
          height: 12px;
          border: 1px solid #000;
          text-align: center;
          vertical-align: middle;
          font-size: 8px;
			

      }

